import{_ as a,c as n,a as r,o as c}from"./app-i2w7PHGN.js";const i={};function d(t,e){return c(),n("div",null,e[0]||(e[0]=[r('<blockquote><p>All in AI，看见未来。 每天精选最值得读的AI文章，帮你筛掉时代的噪音。 以简讯见广度，以深读见洞察。 技术、趋势、思考，一站式掌握AI世界。 欢迎关注公众号「AI Reading Hub」，获取更多AI资讯和技术文章。</p></blockquote><h1 id="_2026-09-24-资讯日报" tabindex="-1"><a class="header-anchor" href="#_2026-09-24-资讯日报"><span>2026-09-24 资讯日报</span></a></h1><h2 id="新闻资讯" tabindex="-1"><a class="header-anchor" href="#新闻资讯"><span>新闻资讯</span></a></h2><h3 id="张江塔尖会拆解ai自进化路径" tabindex="-1"><a class="header-anchor" href="#张江塔尖会拆解ai自进化路径"><span>张江塔尖会拆解AI自进化路径</span></a></h3><p>本次张江塔尖会多位学者指出，真正RSI不是AI局部任务优化，需形成AI自主发现问题、迭代改进的全闭环，代码、AI for Science、具身智能是热门探索方向，距离真正自进化仍有多道瓶颈待突破。<a href="https://mp.weixin.qq.com/s?__biz=MzA3MzI4MjgzMw==&amp;chksm=85bfa1cf4b1f963ab760a02559e388e1aa0bd080ec104bede29e7749800187937ba01f920b43&amp;idx=2&amp;mid=2651059423&amp;sn=c2b561e3cd27cb2f69a3a8e3b178a7f4#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="claude自主发现类crispr新酶系统" tabindex="-1"><a class="header-anchor" href="#claude自主发现类crispr新酶系统"><span>Claude自主发现类CRISPR新酶系统</span></a></h3><p>Anthropic的Claude大模型自主从噬菌体DNA中发现全新类CRISPR酶系统ART，自主分析效率远超人类专家；张锋称这是AI助力生物发现的精彩案例，ART值得研究，目前功能尚不明确。<a href="https://mp.weixin.qq.com/s?__biz=MzA3NTIyODUzNA==&amp;chksm=868996509e77b1ebbcb2c4d59b3accd8c6296a4f3d494c3797b79bceb44240dd212eef31f876&amp;idx=1&amp;mid=2649806091&amp;sn=79e36ba9688250b3baa161094573dbdd#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="claude发现全新dna酶系统art" tabindex="-1"><a class="header-anchor" href="#claude发现全新dna酶系统art"><span>Claude发现全新DNA酶系统ART</span></a></h3><p>Anthropic用950个Claude消耗2.1亿Token，仅21小时就在噬菌体DNA中发现类似CRISPR的全新酶系统ART，经人类实验验证确认，AI改写生命科学科研范式，有望加速攻克严重疾病。<a href="https://mp.weixin.qq.com/s?__biz=MzI3MTA0MTk1MA==&amp;chksm=f076a69a11f8b1e8f9cd472b098e9242464ee92e63acf8cfec1675cb43eb0e8b06d7e67bd37a&amp;idx=1&amp;mid=2652729076&amp;sn=92e41a32264677aeb89866cb673df003#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="产品应用" tabindex="-1"><a class="header-anchor" href="#产品应用"><span>产品应用</span></a></h2><h3 id="_90后ceo掌钉钉-推千问办公迎战ai" tabindex="-1"><a class="header-anchor" href="#_90后ceo掌钉钉-推千问办公迎战ai"><span>90后CEO掌钉钉 推千问办公迎战AI</span></a></h3><p>陈宇森点破当前AI办公的效率假象：个人提效但组织脱节，算力投入飙升却未提升组织绩效。钉钉推出千问办公，以企业上下文为核心做解耦探索破局。<a href="https://mp.weixin.qq.com/s?__biz=MjM5MDE0Mjc4MA==&amp;chksm=bcdb6dd4bbc4d1708563cd7d97e1dbb71e989f3f55c6778d6da1de11abd26e62eef38151007e&amp;idx=1&amp;mid=2651293888&amp;sn=14317101a03d9b75120aa659e07c54f5#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="灵初较真机器人训练数据质量" tabindex="-1"><a class="header-anchor" href="#灵初较真机器人训练数据质量"><span>灵初较真机器人训练数据质量</span></a></h3><p>灵初智能：机器人训练不能光堆数据时长，弱配对数据无法直接使用。逆向从机器人真实操作生成对应人手数据得到强配对数据，定制任务1-2天即可适配，成功率达99%。<a href="https://mp.weixin.qq.com/s?__biz=MzIzNjc1NzUzMw==&amp;chksm=e9abf671be51821589da66aab30ab54747496e232e177b95c4e978372d4545c66df84c0a1780&amp;idx=1&amp;mid=2247926680&amp;sn=a189450174b06c12dabc4d729aa9d175#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><p style="text-align:center;"><img id="weixin_qr" src="https://meikan-public-images.oss-cn-beijing.aliyuncs.com/imeikan/assets/2025-05-18234303-hub.png" style="max-width:800px;object-fit:cover;"></p><p><a href="https://aireadinghub.com/" target="_blank" rel="noopener noreferrer">官网：www.AiReadingHub.com</a></p>',16)]))}const s=a(i,[["render",d]]),p=JSON.parse('{"path":"/posts/2026-09-24.html","title":"AI日报：张江塔尖会拆解AI自进化路径; Claude自主发现类CRISPR新酶系统; Claude发现全新DNA酶系统ART","lang":"zh-CN","frontmatter":{"date":"2026-09-24T00:00:00.000Z","title":"AI日报：张江塔尖会拆解AI自进化路径; Claude自主发现类CRISPR新酶系统; Claude发现全新DNA酶系统ART"},"headers":[{"level":2,"title":"新闻资讯","slug":"新闻资讯","link":"#新闻资讯","children":[{"level":3,"title":"张江塔尖会拆解AI自进化路径","slug":"张江塔尖会拆解ai自进化路径","link":"#张江塔尖会拆解ai自进化路径","children":[]},{"level":3,"title":"Claude自主发现类CRISPR新酶系统","slug":"claude自主发现类crispr新酶系统","link":"#claude自主发现类crispr新酶系统","children":[]},{"level":3,"title":"Claude发现全新DNA酶系统ART","slug":"claude发现全新dna酶系统art","link":"#claude发现全新dna酶系统art","children":[]}]},{"level":2,"title":"产品应用","slug":"产品应用","link":"#产品应用","children":[{"level":3,"title":"90后CEO掌钉钉 推千问办公迎战AI","slug":"_90后ceo掌钉钉-推千问办公迎战ai","link":"#_90后ceo掌钉钉-推千问办公迎战ai","children":[]},{"level":3,"title":"灵初较真机器人训练数据质量","slug":"灵初较真机器人训练数据质量","link":"#灵初较真机器人训练数据质量","children":[]}]}],"git":{"updatedTime":1790328069000,"contributors":[{"name":"GitHub Actions","username":"","email":"actions@github.com","commits":1}],"changelog":[{"hash":"1b8b1a93db4d96898235bbb08061fc22765f52ec","time":1790328069000,"email":"actions@github.com","author":"GitHub Actions","message":"Auto-commit generated files on 2026-09-25T09:21:09.962Z"}]},"filePathRelative":"posts/2026-09-24.md","excerpt":"<blockquote>\\n<p>All in AI，看见未来。 每天精选最值得读的AI文章，帮你筛掉时代的噪音。 以简讯见广度，以深读见洞察。 技术、趋势、思考，一站式掌握AI世界。\\n欢迎关注公众号「AI Reading Hub」，获取更多AI资讯和技术文章。</p>\\n</blockquote>\\n<h1>2026-09-24 资讯日报</h1>\\n<h2>新闻资讯</h2>\\n<h3>张江塔尖会拆解AI自进化路径</h3>\\n<p>本次张江塔尖会多位学者指出，真正RSI不是AI局部任务优化，需形成AI自主发现问题、迭代改进的全闭环，代码、AI for Science、具身智能是热门探索方向，距离真正自进化仍有多道瓶颈待突破。<a href=\\"https://mp.weixin.qq.com/s?__biz=MzA3MzI4MjgzMw==&amp;chksm=85bfa1cf4b1f963ab760a02559e388e1aa0bd080ec104bede29e7749800187937ba01f920b43&amp;idx=2&amp;mid=2651059423&amp;sn=c2b561e3cd27cb2f69a3a8e3b178a7f4#rd\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">&gt;阅读原文</a></p>"}');export{s as comp,p as data};
